@Component("productPricing-handler")
@ProcessingGroup("productPricing-processing-group")
public class ProductPricingEventHandler {
	
	// core constructor
	ProductPricingEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateProductPricingEvent
     */
    @EventHandler
    public void handle( CreateProductPricingEvent event) {
        entityManager.persist(new ProductPricing(event.getProductPricingId(), event.getListPrice(), event.getSalePrice(), event.getValidFrom(), event.getValidTo(), event.getVariant(), event.getChannel()));
    }

    /*
     * @param	event UpdateProductPricingEvent
     */
    @EventHandler
    public ProductPricing handle( UpdateProductPricingEvent event) {
    	entityManager.merge(new ProductPricing(event.getProductPricingId(), event.getListPrice(), event.getSalePrice(), event.getValidFrom(), event.getValidTo(), event.getVariant(), event.getChannel()));
    }
    
    /*
     * @param	event DeleteProductPricingEvent
     */
    @EventHandler
    public void on( DeleteProductPricingEvent event) {
    	ProductPricing entity = new ProductPricing();
   
    	// ------------------------------------------
    	// apply the ProductPricingId
    	// ------------------------------------------
    	entity.setProductPricingId( event.getProductPricingId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ProductPricingRepository productPricingEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ProductPricingEventHandler.class.getName());

}
